    p=subprocess.run([sys.executable,'-B','/workspace/submission/main.py'],input=raw,
                     stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd='/workspace')
    return p.stdout,p.stderr,p.returncode
def decode(raw):
    def pairs(items):
        d={}
        for k,v in items:
            if k in d: raise ValueError('dup')
            d[k]=v
        return d
    return json.loads(raw.decode(),object_pairs_hook=pairs)
